const MAX_WORDS:usize=32;const MAX_INPUT:usize=307;
fn eq(v:[]const i64,s:usize,n:usize,t:usize,m:usize)bool{if(n!=m)return false;for(0..n)|i|{if(v[s+i]!=v[t+i])return false;}return true;}
export fn shortest_word_distance(ptr:?[*]const i64,length:usize)i64{if(ptr==null or length<1 or length>MAX_INPUT+1)return -1;const v=ptr.?[0..length];if(v[0]<2 or v[0]>32)return -1;const n:usize=@intCast(v[0]);var starts=[_]usize{0}**MAX_WORDS;var sizes=[_]usize{0}**MAX_WORDS;var p:usize=1;for(0..n)|i|{if(p>=length)return -1;const z=v[p];p+=1;if(z<1 or z>8 or p+@as(usize,@intCast(z))>length)return -1;starts[i]=p;sizes[i]=@intCast(z);for(v[p..][0..sizes[i]])|b|{if(!((b>=65 and b<=90) or (b>=97 and b<=122)))return -1;}p+=sizes[i];}var ts=[_]usize{0}**2;var tn=[_]usize{0}**2;for(0..2)|t|{if(p>=length)return -1;const z=v[p];p+=1;if(z<1 or z>8 or p+@as(usize,@intCast(z))>length)return -1;ts[t]=p;tn[t]=@intCast(z);for(v[p..][0..tn[t]])|b|{if(!((b>=65 and b<=90) or (b>=97 and b<=122)))return -1;}p+=tn[t];}if(p!=length or eq(v,ts[0],tn[0],ts[1],tn[1]))return -1;var h0=false;var h1=false;var best=n;for(0..n)|i|{const a=eq(v,starts[i],sizes[i],ts[0],tn[0]);const b=eq(v,starts[i],sizes[i],ts[1],tn[1]);h0=h0 or a;h1=h1 or b;for(0..n)|j|{const c=eq(v,starts[j],sizes[j],ts[0],tn[0]);const d=eq(v,starts[j],sizes[j],ts[1],tn[1]);if((a and d) or (b and c)){const delta=if(i>j)i-j else j-i;if(delta<best)best=delta;}}}return if(h0 and h1) @intCast(best) else -1;}
